1	// Unit tests for hybrid/program_buffer.hpp.
2	// Pure compile-time and recording-bus tests -- no SystemC, no hardware.
3	
4	#include "hybrid/program_buffer.hpp"
5	
6	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
7	#include <doctest.h>
8	
9	#include <array>
10	#include <cstdint>
11	#include <stdexcept>
12	#include <vector>
13	
14	using namespace hybrid;
15	
16	// ---- Recording DmiBus stub -------------------------------------------------
17	// Captures all writes; returns configurable values per register address.
18	struct RecBus
19	{
20	    struct Op { uint8_t reg; uint32_t val; };
21	
22	    std::vector<Op> writes;
23	    // Per-register read sequences: each call pops the front value.
24	    // If the list is empty, returns 0.
25	    std::map<uint8_t, std::vector<uint32_t>> read_seq;
26	
27	    void write(uint8_t reg, uint32_t val) { writes.push_back({reg, val}); }
28	
29	    uint32_t read(uint8_t reg)
30	    {
31	        auto it = read_seq.find(reg);
32	        if (it == read_seq.end() || it->second.empty()) return 0u;
33	        uint32_t v = it->second.front();
34	        it->second.erase(it->second.begin());
35	        return v;
36	    }
37	};
38	
39	// ---- kExecProgbufCmd constant tests ----------------------------------------
40	
41	TEST_CASE("kExecProgbufCmd: postexec=1, transfer=0, cmdtype=AccessRegister")
42	{
43	    CHECK(((kExecProgbufCmd >> 18) & 1u) == 1u);   // postexec set
44	    CHECK(((kExecProgbufCmd >> 17) & 1u) == 0u);   // transfer NOT set (unlike access_register_command)
45	    CHECK(((kExecProgbufCmd >> 24) & 0xFFu) == 0u); // cmdtype = AccessRegister (0)
46	}
47	
48	TEST_CASE("kEbreak encodes a standard ebreak instruction")
49	{
50	    // ebreak = funct12=000000000001, rs1=0, funct3=0, rd=0, opcode=SYSTEM(0x73)
51	    CHECK(kEbreak == 0x00100073u);
52	}
53	
54	TEST_CASE("kProgbufMaxInsns leaves room for ebreak")
55	{
56	    // 16 slots total (progbuf0..progbuf15); 15 for payload, 1 for ebreak
57	    CHECK(kProgbufMaxInsns == 15u);
58	    CHECK(kProgbuf0 == 0x20u);
59	}
60	
61	// ---- Instruction encoder tests ---------------------------------------------
62	
63	TEST_CASE("encode_vsetvl: known encodings")
64	{
65	    // vsetvl x0, t0, t1  (rd=0, rs1=5, rs2=6)
66	    // RVV 1.0: funct7=1000000, opcode=1010111(0x57), funct3=111
67	    // 1|000000|00110|00101|111|00000|1010111 = 0x8062F057
68	    CHECK(encode_vsetvl(0, 5, 6) == 0x8062F057u);
69	
70	    // vsetvl x1, a0, a1  (rd=1, rs1=10, rs2=11)
71	    // 1|000000|01011|01010|111|00001|1010111 = 0x80B570D7
72	    CHECK(encode_vsetvl(1, 10, 11) == 0x80B570D7u);
73	
74	    // vsetvl x0, x0, x0  (all-zero registers)
75	    // 1|000000|00000|00000|111|00000|1010111 = 0x80007057
76	    CHECK(encode_vsetvl(0, 0, 0) == 0x80007057u);
77	}
78	
79	TEST_CASE("encode_csrrw: known encodings")
80	{
81	    // csrrw x0, mstatus(0x300), t0(x5)
82	    // [31:20]=0x300, [19:15]=5, [14:12]=001, [11:7]=0, [6:0]=0x73
83	    // = 0x30029073
84	    CHECK(encode_csrrw(0, 0x300, 5) == 0x30029073u);
85	
86	    // csrrw x0, vstart(0x008), t1(x6)
87	    // [31:20]=0x008, [19:15]=6, [14:12]=001, [11:7]=0, [6:0]=0x73
88	    // = 0x00831073
89	    CHECK(encode_csrrw(0, 0x008, 6) == 0x00831073u);
90	
91	    // csrrw x0, vxsat(0x009), t0(x5)
92	    // [31:20]=0x009, [19:15]=5, [14:12]=001, [11:7]=0, [6:0]=0x73
93	    // = 0x00929073
94	    CHECK(encode_csrrw(0, 0x009, 5) == 0x00929073u);
95	}
96	
97	TEST_CASE("encode_vle8_v: known encodings (golden hex from riscv64-elf-as)")
98	{
99	    // vle8.v vd, (rs1): unit-stride load, EEW=8. vm=1, width=000, mop=00,
100	    // mew=0, nf=000, lumop=00000, opcode LOAD-FP=0x07. The single set upper
101	    // bit is vm at bit 25. Verified with `riscv64-elf-as -march=rv64gcv`.
102	    CHECK(encode_vle8_v(0, 7)  == 0x02038007u);   // vle8.v v0,(x7)
103	    CHECK(encode_vle8_v(3, 7)  == 0x02038187u);   // vle8.v v3,(x7)
104	    CHECK(encode_vle8_v(31, 7) == 0x02038F87u);   // vle8.v v31,(x7)
105	}
