107	TEST_CASE("encode_vse8_v: known encodings (golden hex from riscv64-elf-as)")
108	{
109	    // vse8.v vs3, (rs1): unit-stride store, EEW=8. Same fields as vle8.v but
110	    // opcode STORE-FP=0x27. Verified with `riscv64-elf-as -march=rv64gcv`.
111	    CHECK(encode_vse8_v(0, 7)  == 0x02038027u);   // vse8.v v0,(x7)
112	    CHECK(encode_vse8_v(3, 7)  == 0x020381A7u);   // vse8.v v3,(x7)
113	    CHECK(encode_vse8_v(31, 7) == 0x02038FA7u);   // vse8.v v31,(x7)
114	}
