116	// ---- exec_progbuf behavioral tests -----------------------------------------
117	
118	TEST_CASE("exec_progbuf: single instruction - writes insn, ebreak, exec command")
119	{
120	    RecBus bus;
121	    const std::array<uint32_t, 1> insns{0xDEADBEEFu};
122	    const bool ok = exec_progbuf(bus, insns);
123	
124	    REQUIRE(ok == true);
125	
126	    // Writes (in order):
127	    //   progbuf0 = insn
128	    //   progbuf1 = ebreak
129	    //   command  = kExecProgbufCmd
130	    // (no pre-clear because bus returns 0 for abstractcs -> no cmderr)
131	    REQUIRE(bus.writes.size() == 3u);
132	    CHECK(bus.writes[0].reg == kProgbuf0);
133	    CHECK(bus.writes[0].val == 0xDEADBEEFu);
134	    CHECK(bus.writes[1].reg == kProgbuf0 + 1);
135	    CHECK(bus.writes[1].val == kEbreak);
136	    CHECK(bus.writes[2].reg == 0x17u);       // kCommandReg
137	    CHECK(bus.writes[2].val == kExecProgbufCmd);
138	}
