140	TEST_CASE("exec_progbuf: max instructions fills progbuf0..14, ebreak at progbuf15")
141	{
142	    RecBus bus;
143	    std::array<uint32_t, 15> insns{};
144	    for (uint32_t i = 0; i < 15; ++i) insns[i] = 0xAA000000u | i;
145	
146	    const bool ok = exec_progbuf(bus, insns);
147	    REQUIRE(ok == true);
148	
149	    // 15 payload writes + ebreak + exec command = 17 writes
150	    REQUIRE(bus.writes.size() == 17u);
151	    for (std::size_t i = 0; i < 15; ++i) {
152	        CHECK(bus.writes[i].reg == kProgbuf0 + i);
153	        CHECK(bus.writes[i].val == (0xAA000000u | i));
154	    }
155	    CHECK(bus.writes[15].reg == kProgbuf0 + 15u);
156	    CHECK(bus.writes[15].val == kEbreak);
157	    CHECK(bus.writes[16].reg == 0x17u);
158	    CHECK(bus.writes[16].val == kExecProgbufCmd);
159	}
