161	TEST_CASE("exec_progbuf: 16 instructions throws - no bus writes happen")
162	{
163	    RecBus bus;
164	    std::array<uint32_t, 16> insns{};
165	    CHECK_THROWS_AS(exec_progbuf(bus, insns), std::runtime_error);
166	    CHECK(bus.writes.empty());
167	}
