169	TEST_CASE("exec_progbuf: clears sticky cmderr before issuing exec command")
170	{
171	    RecBus bus;
172	    // abstractcs returns cmderr=set on the first read (pre-exec check),
173	    // then 0 thereafter (poll + final check)
