1	// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
2	// ops against the RISC-V Debug Module. The orchestration is testable in
3	// isolation by injecting a recording bus.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/resume_driver.hpp"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_regfile_xfer.hpp"
10	
11	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
12	#include <doctest.h>
13	
14	#include <cstdint>
15	#include <deque>
16	#include <optional>
17	#include <vector>
18	
19	namespace {
20	
21	// DMI register addresses from RISC-V Debug Spec 1.0.
22	constexpr uint8_t kDmcontrol  = 0x10;
23	constexpr uint8_t kDmstatus   = 0x11;
24	constexpr uint8_t kAbstractcs = 0x16;
25	constexpr uint8_t kCommand    = 0x17;
26	constexpr uint8_t kData0      = 0x04;
27	constexpr uint8_t kData1      = 0x05;
28	
29	// CSR numbers from Debug Spec.
30	constexpr uint16_t kCsrDpc = 0x7B1;
31	
32	struct DmiOp
33	{
34	  enum class Kind
35	  {
36	    Write,
37	    Read,
38	  };
39	  Kind kind;
40	  uint8_t reg;
41	  uint32_t value;  // for writes only
42	};
43	
44	struct RecordingBus final : hybrid::DmiBus
45	{
46	  std::vector<DmiOp> ops;
47	
48	  // Test-controlled response values for reads.
49	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
50	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
51	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
52	
53	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
54	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
55	  // fallback). Models real hardware and -- unlike positional queueing -- is
56	  // robust to however many unrelated abstract ops precede the targeted write.
57	  std::optional<uint16_t> fail_csr_write;
58	
59	  void write(uint8_t reg, uint32_t value) override
60	  {
61	    ops.push_back({DmiOp::Kind::Write, reg, value});
62	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
63	      cmderr_sticky_ = false;  // W1C clear
64	    if (reg == kCommand && fail_csr_write) {
65	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
66	      const bool is_write = ((value >> 16) & 1u) != 0u;
67	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
68	        cmderr_sticky_ = true;
69	    }
70	  }
71	
72	  auto read(uint8_t reg) -> uint32_t override
73	  {
74	    ops.push_back({DmiOp::Kind::Read, reg, 0});
75	    if (reg == kDmstatus) return dmstatus_value;
76	    if (reg == kAbstractcs) {
77	      if (cmderr_sticky_) return kCmderrMask;
78	      if (!abstractcs_queue.empty()) {
79	        auto v = abstractcs_queue.front();
80	        abstractcs_queue.pop_front();
81	        return v;
82	      }
83	      return abstractcs_value;
84	    }
85	    return 0;
86	  }
87	
88	private:
89	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
90	  bool cmderr_sticky_ = false;
91	};
92	
93	auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
94	{
95	  hybrid_state_v1 s{};
96	  s.magic = HYBRID_STATE_MAGIC;
97	  s.version = HYBRID_STATE_VERSION;
98	  s.flags = HYBRID_FLAG_RV64;
99	  s.pc = pc;
100	  s.priv = 3;
101	  s.gpr[10] = x10;
102	  return s;
103	}
104	
105	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
106	  -> std::vector<uint32_t>
107	{
108	  std::vector<uint32_t> values;
109	  for (const auto& op : ops)
110	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
111	      values.push_back(op.value);
112	  return values;
113	}
114	
115	auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
116	{
117	  std::size_t n = 0;
118	  for (const auto& op : ops)
119	    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
120	  return n;
121	}
122	
123	}  // namespace
124	
125	TEST_CASE("resume halts the hart before any abstract command")
126	{
127	  RecordingBus bus;
128	  // dmstatus answers halted+resumeack so poll loops finish on the first read.
129	  bus.dmstatus_value = (1u << 9) | (1u << 17);
130	
131	  hybrid::ResumeDriver driver(bus);
132	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x10=*/0xdeadbeef));
133	
134	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
135	  // accepted; the second write must add haltreq while keeping dmactive set.
136	  REQUIRE(bus.ops.size() >= 2);
137	
138	  const auto& prime = bus.ops[0];
139	  CHECK(prime.kind == DmiOp::Kind::Write);
140	  CHECK(prime.reg == kDmcontrol);
141	  CHECK((prime.value & 1u) == 1u);                  // dmactive
142	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
143	
144	  const auto& halt = bus.ops[1];
145	  CHECK(halt.kind == DmiOp::Kind::Write);
146	  CHECK(halt.reg == kDmcontrol);
147	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
148	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
149	}
150	
151	TEST_CASE("resume programs x1..x31 via DATA0/DATA1 + COMMAND, skipping x0")
152	{
153	  RecordingBus bus;
154	  bus.dmstatus_value = (1u << 9) | (1u << 17);
155	
156	  auto s = rv64_state(0x80001000, 0xdeadbeef);
157	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0xa00000000ULL + i;
158	
159	  hybrid::ResumeDriver driver(bus);
160	  driver.resume(s);
161	
162	  std::vector<uint32_t> cmds;
163	  for (const auto& op : bus.ops)
164	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
165	      cmds.push_back(op.value);
166	
167	  CHECK(cmds.size() >= 31);
168	
169	  for (int i = 1; i < 32; ++i) {
170	    const auto expect =
171	      hybrid::access_register_command(hybrid::regno_gpr(i),
172	                                      hybrid::AarSize::Bits64, /*write=*/true);
173	    CHECK(cmds[i - 1] == expect);
174	  }
175	
176	  for (const auto& cmd : cmds) {
177	    const uint16_t regno = cmd & 0xffffu;
178	    CHECK(regno != hybrid::regno_gpr(0));
179	  }
180	}
181	
182	TEST_CASE("resume writes DPC = state.pc")
183	{
184	  RecordingBus bus;
185	  bus.dmstatus_value = (1u << 9) | (1u << 17);
186	
187	  constexpr uint64_t pc = 0x12345678'9ABCDEF0ULL;
188	  hybrid::ResumeDriver driver(bus);
189	  driver.resume(rv64_state(pc, 0));
190	
191	  // Look for the COMMAND write that targets CSR DPC (regno=0x7B1).
192	  std::vector<std::size_t> dpc_cmd_indices;
193	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
194	    const auto& op = bus.ops[i];
195	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
196	        && (op.value & 0xffffu) == kCsrDpc) {
197	      dpc_cmd_indices.push_back(i);
198	    }
199	  }
200	  REQUIRE(dpc_cmd_indices.size() == 1);
201	
202	  // Immediately preceding writes must set DATA0=low32(pc), DATA1=high32(pc).
203	  const auto cmd_idx = dpc_cmd_indices[0];
204	  REQUIRE(cmd_idx >= 2);
205	  const auto& d0 = bus.ops[cmd_idx - 2];
206	  const auto& d1 = bus.ops[cmd_idx - 1];
207	  CHECK(d0.kind == DmiOp::Kind::Write);
208	  CHECK(d0.reg == kData0);
209	  CHECK(d0.value == uint32_t(pc & 0xffffffffu));
210	  CHECK(d1.kind == DmiOp::Kind::Write);
211	  CHECK(d1.reg == kData1);
212	  CHECK(d1.value == uint32_t((pc >> 32) & 0xffffffffu));
213	}
214	
215	TEST_CASE("resume issues resumereq after register programming")
216	{
217	  RecordingBus bus;
218	  bus.dmstatus_value = (1u << 9) | (1u << 17);
219	
220	  hybrid::ResumeDriver driver(bus);
221	  driver.resume(rv64_state(0x80001000, 0));
222	
223	  // The last DMCONTROL write must clear haltreq and set resumereq.
224	  const auto dmctl_writes = find_write(bus.ops, kDmcontrol);
225	  REQUIRE(dmctl_writes.size() >= 2);
226	  const auto last = dmctl_writes.back();
227	  CHECK((last & 1u) == 1u);                  // dmactive still on
228	  CHECK(((last >> 31) & 1u) == 0u);          // haltreq cleared
229	  CHECK(((last >> 30) & 1u) == 1u);          // resumereq set
230	}
231	
232	TEST_CASE("resume polls DMSTATUS for halted before programming registers")
233	{
234	  RecordingBus bus;
235	  bus.dmstatus_value = (1u << 9) | (1u << 17);
236	
237	  hybrid::ResumeDriver driver(bus);
238	  driver.resume(rv64_state(0x80001000, 0));
239	
240	  // At least one DMSTATUS read happened, and it occurred before the first
241	  // DATA0/DATA1 write.
242	  std::optional<std::size_t> first_dmstatus_read;
243	  std::optional<std::size_t> first_data_write;
244	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
245	    const auto& op = bus.ops[i];
246	    if (op.kind == DmiOp::Kind::Read && op.reg == kDmstatus
247	        && !first_dmstatus_read)
248	      first_dmstatus_read = i;
249	    if (op.kind == DmiOp::Kind::Write && op.reg == kData0 && !first_data_write)
250	      first_data_write = i;
251	  }
252	  REQUIRE(first_dmstatus_read);
253	  REQUIRE(first_data_write);
254	  CHECK(*first_dmstatus_read < *first_data_write);
255	}
256	
257	TEST_CASE("resume rejects a state with wrong magic")
258	{
259	  RecordingBus bus;
260	  hybrid::ResumeDriver driver(bus);
261	
262	  hybrid_state_v1 bad{};
263	  bad.version = HYBRID_STATE_VERSION;
264	  bad.magic = 0xDEADBEEFu;
265	  CHECK_THROWS(driver.resume(bad));
266	}
267	
268	TEST_CASE("resume issues exactly one COMMAND per programmed register")
269	{
270	  RecordingBus bus;
271	  bus.dmstatus_value = (1u << 9) | (1u << 17);
272	
273	  hybrid::ResumeDriver driver(bus);
274	  driver.resume(rv64_state(0x80001000, 0));
275	
276	  // x1..x31 + DPC at minimum (x0 skipped). We do not yet program FPR/CSR/V.
277	  CHECK(count_writes_to(bus.ops, kCommand) >= 32u);
278	}
279	
280	namespace {
281	
282	auto cmd_regnos(const std::vector<DmiOp>& ops) -> std::vector<uint16_t>
283	{
284	  std::vector<uint16_t> ns;
285	  for (const auto& op : ops)
286	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
287	      ns.push_back(static_cast<uint16_t>(op.value & 0xffffu));
288	  return ns;
289	}
290	
291	auto contains_regno(const std::vector<uint16_t>& ns, uint16_t regno) -> bool
292	{
293	  for (auto n : ns) if (n == regno) return true;
294	  return false;
295	}
296	
297	}  // namespace
298	
299	TEST_CASE("resume does NOT program M-mode CSRs/PMP via DM Abstract Commands; "
300	          "those fields are pass-through-merged at drain time instead")
301	{
302	  RecordingBus bus;
303	  bus.dmstatus_value = (1u << 9) | (1u << 17);
304	
