581	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
582	          "before the architectural V-CSR restore and counter restore")
583	{
584	  RecordingBus bus;
585	  bus.dmstatus_value = (1u << 9) | (1u << 17);
586	
587	  auto s = rv64_state(0x80001000, 0);
588	  s.flags  |= HYBRID_FLAG_V;
589	  s.vlenb  = 64;
590	  s.vl     = 16;
591	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
592	  s.vstart = 7;
593	
594	  hybrid::ResumeDriver driver(bus);
595	  driver.resume(s);
596	
597	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
598	  std::vector<int> missing;
599	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
600	  for (uint16_t v = 0; v < 32; ++v) {
601	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
602	    std::optional<std::size_t> at;
603	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
604	      const auto& op = bus.ops[i];
605	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
606	          && op.value == want) { at = i; break; }
607	    }
608	    if (!at) { missing.push_back(v); continue; }
609	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
610	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
611	  }
612	  CHECK(missing.empty());
613	  REQUIRE(first_vle_idx.has_value());
614	  REQUIRE(last_vle_idx.has_value());
615	
616	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
617	  //     first and last register.
618	  auto x7_gpa_staged = [&](uint64_t gpa) {
619	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
620	      const auto& op = bus.ops[i];
621	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
622	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
623	          && ((op.value >> 16) & 1u)) {
624	        const auto& d0 = bus.ops[i - 2];
625	        const auto& d1 = bus.ops[i - 1];
626	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
627	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
628	          return true;
629	      }
630	    }
631	    return false;
632	  };
633	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa));
634	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa + 31ull * HYBRID_VLEN_BYTES_MAX));
635	
636	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
637	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
638	  //     (so the vle8.v insns cannot pollute the resumed counters).
639	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
640	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
641	    const auto& op = bus.ops[i];
642	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
643	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
644	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
645	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
646	  }
647	  REQUIRE(vstart_cmd_idx.has_value());
648	  REQUIRE(mcycle_cmd_idx.has_value());
649	  CHECK(*last_vle_idx < *vstart_cmd_idx);
650	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
651	}
