TEST_CASE("B8: capture polls allresumeack after resumereq")
{
  // The capture sequence halts the hart, reads CSRs, then resumes. Without
  // a poll for DmstatusAllresumeack the next sc_start may proceed before
  // the hart actually re-runs; warmup-window accounting then drifts.
  // Pin the contract: after writing resumereq, the bus must observe a
  // read of kDmstatus (the poll) before any further DMCONTROL traffic.
  RecordingBus bus;
  prime_snapshot_bus(bus, /*mcycle=*/1, /*minstret=*/1);

  hybrid::MeasureStartSnapshot snap(/*k=*/1, bus);
  snap.observe_commit();
  REQUIRE(snap.snapshot_reached());

  // Find the index of the resumereq write; assert at least one
  // kDmstatus read appears after it.
  std::size_t resume_idx = bus.ops.size();
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == hybrid::test::DmiOp::Kind::Write
        && op.reg == RD::kDmcontrol
        && (op.value & RD::kDmcontrolResumereq)) {
      resume_idx = i;
      break;
    }
  }
  REQUIRE(resume_idx < bus.ops.size());

  bool saw_dmstatus_read_after_resume = false;
  for (std::size_t i = resume_idx + 1; i < bus.ops.size(); ++i) {
    if (bus.ops[i].kind == hybrid::test::DmiOp::Kind::Read
        && bus.ops[i].reg == RD::kDmstatus) {
      saw_dmstatus_read_after_resume = true;
      break;
    }
  }
  CHECK(saw_dmstatus_read_after_resume);
}

